// replace-face: a cylinder (radius 10, 20 tall)'s side replaced up to a coaxial cylinder of radius 10, offset 2 mm
export function c003(context is Context, id is Id)
{
    const bases = newSketchOnPlane(context, id + "bases", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(bases, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(bases);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "bases"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const tools = newSketchOnPlane(context, id + "tools", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(tools, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(tools);
    extrude(context, id + "tool", { "entities" : qSketchRegion(id + "tools"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    replaceFace(context, id + "replace1", { "replaceFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), "templateFace" : qOwnedByBody(qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "oppositeSense" : false, "offset" : 2 * millimeter });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

